contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: hash to lock, and an amount to send when locking (must be 1 ether to succeed).
    // Also provide a boolean doSettle to decide whether we call settle after lockInGuess.
    function run(bytes32 h, uint lockAmount, bool doSettle) public payable {
        require(address(this).balance >= lockAmount);

        // read initial balance of c
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Attempt to lock in a guess (may revert). We must call top-level.
        bool lockedReverted;
        try c.lockInGuess{value: lockAmount}(h) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // If lock reverted, then c's state should be unchanged and no ether moved from this contract to c.
        // We capture balance after attempt to compare later.
        uint afterLockC = address(c).balance;
        uint afterLockThis = address(this).balance;

        // Optionally call settle (may revert). Only meaningful if lock succeeded.
        bool settleReverted;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
            } catch {
                settleReverted = true;
            }
        } else {
            settleReverted = true; // treat as not called
        }

        // Balance after optional settle
        uint afterAllC = address(c).balance;
        uint afterAllThis = address(this).balance;

        // General rule (single assert):
        // 1) If lockInGuess reverted, c's balance didn't increase and this contract's balance didn't decrease.
        // 2) If lockInGuess succeeded and we didn't call settle, then c's balance increased by lockAmount and this contract decreased by lockAmount.
        // 3) If lockInGuess succeeded and settle was called and did not revert, then this contract's net gain from c is at most 2 ether and c's balance decreased by at most 2 ether.
        // Combine into one assert expression referencing observed balances and revert flags.
        assert(
            (
                lockedReverted && afterLockC == beforeC && afterLockThis == beforeThis
            ) || (
                !lockedReverted && !doSettle && afterLockC == beforeC + lockAmount && afterLockThis == beforeThis - lockAmount
            ) || (
                !lockedReverted && doSettle && !settleReverted &&
                // when settle succeeds, this contract's balance cannot increase by more than 2 ether relative to afterLockThis
                (afterAllThis <= afterLockThis + 2 ether) &&
                // and contract c's balance decreased correspondingly by at most 2 ether
                (afterLockC >= afterAllC) && (afterLockC - afterAllC <= 2 ether)
            ) || (
                // if settle was called but reverted, then balances should remain as afterLock
                !lockedReverted && doSettle && settleReverted && afterAllC == afterLockC && afterAllThis == afterLockThis
            )
        );
    }

    // Allow contract to receive Ether so it can fund lockInGuess calls
    receive() external payable {}
}

