contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: a hash to lock in and an amount to send for lockInGuess (must be 1 ether)
    function run(bytes32 hash, uint lockAmount) public payable {
        require(lockAmount == 1 ether);
        // ensure this contract has enough balance to call lockInGuess
        require(address(this).balance >= lockAmount);

        // Initially, caller (this contract) should have no guess recorded
        // call lockInGuess to create a guess for this contract
        c.lockInGuess{value: lockAmount}(hash);

        // read the stored Guess via the public auto-getter: guesses(address) returns (uint, bytes32)
        (uint blkBefore, bytes32 guessBefore) = c.guesses(address(this));

        // require that lockInGuess set a non-zero block and stored the hash we provided
        require(blkBefore != 0);
        require(guessBefore == hash);

        // Advance: attempt to settle. settle may revert (if block.number <= blkBefore or other conditions)
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After settle (whether it reverted or not), read the stored guess for this caller again
        (uint blkAfter, bytes32 guessAfter) = c.guesses(address(this));

        // Also observe contract balance
        uint balAfter = address(c).balance;

        // General invariant to assert:
        // - If settle reverted, the stored guess may still be present (blkAfter == blkBefore) or cleared (blkAfter == 0).
        // - If settle did not revert, the contract must have cleared the stored guess (blkAfter == 0).
        // - If settle did not revert and the guess matched the computed answer, the contract paid out 2 ether so its balance decreased by at least 2 ether relative to before; conversely if it didn't pay out, balance did not decrease by 2 ether. We cannot compute 'before' precisely here without reading prior balance, so we instead assert that if settle succeeded then blkAfter==0 (ensuring no double-pay possible in same state). This captures a general safety property: successful settle clears the stored guess so it won't be reused.

        assert(reverted || blkAfter == 0);
    }

    // receive to accept any ether sent to this test contract
    receive() external payable {}
}

