        c.lockInGuess{value: lockAmount}(hash);

        // Read the stored Guess via the public auto-getter: guesses(address) is NOT public in C,
        // so we can only observe via calls that are public. C does not provide a getter for guesses,
        // but the constructor and functions change address(c).balance and settle behavior is observable.
        // To detect whether settle succeeded, use try/catch and then assert that on success the caller's
        // recorded block was cleared by observing that a second call to lockInGuess is allowed (requires previous block == 0).

        // Attempt to call settle and record whether it reverted
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now, try to call lockInGuess again with the same required payment: if previous guess was cleared
        // the call should succeed; if not cleared it should revert due to require(guesses[msg.sender].block == 0).
        bool secondReverted;
        // ensure we have the ether to call again
        require(address(this).balance >= lockAmount);
        try c.lockInGuess{value: lockAmount}(hash) {
            secondReverted = false;
            // If it succeeded, cleanup by calling settle (may or may not succeed; ignore)
            try c.settle() { } catch { }
        } catch {
            secondReverted = true;
        }

        // General rule: if the first settle did not revert, then the stored guess must have been cleared,
        // which makes lockInGuess allowed and thus secondReverted must be false. Conversely, if settle reverted,
        // secondReverted may be true or false; we only assert the implication.
        assert(reverted || !secondReverted);
    }

    receive() external payable {}
}

