    // - hash: the bytes32 guess to lock in
    // - sendAmount: must be exactly 1 ether to call lockInGuess
    function run(bytes32 hash, uint sendAmount) public payable {
        require(sendAmount == 1 ether);
        require(address(this).balance >= sendAmount);

        // Record contract balance before locking
        uint beforeBalance = address(c).balance;

        // Lock in a guess for this caller (this contract) paying exactly 1 ether
        c.lockInGuess{value: sendAmount}(hash);

        // After locking, the contract should have increased by exactly 1 ether
        uint afterLockBalance = address(c).balance;

        // Try calling settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Observe contract balance after settle attempt
        uint afterSettleBalance = address(c).balance;

        // General invariant to assert:
        // 1) The lockInGuess must have increased c.balance by exactly 1 ether.
        // 2) If settle reverted then no further guarantees about balance change (but the assert must allow that).
        // 3) If settle did NOT revert, then either:
        //    a) afterSettleBalance == afterLockBalance (no payout happened), or
        //    b) afterSettleBalance + 2 ether == afterLockBalance (the contract paid out 2 ether to caller)
        //    (i.e., the only allowed change on a successful settle is possibly a 2 ether payout)
        // Combine these into a single assert over observable values and the revert flag.

        bool lockIncreasedExactlyOne = (afterLockBalance == beforeBalance + 1 ether);

        bool onSuccessfulSettleBalanceOk = (
            (afterSettleBalance == afterLockBalance) ||
            (afterSettleBalance + 2 ether == afterLockBalance)
        );

        assert(lockIncreasedExactlyOne && (settleReverted || onSuccessfulSettleBalanceOk));
    }

    receive() external payable {}
}

