        // - If lockInGuess succeeded then some guess was recorded: that implies c had accepted 1 ether and increased its balance by 1 ether.
        //   Therefore bal is at least increased by lockAmount when lockSucceeded (we only ever sent lockAmount here).
        // - If lockInGuess failed then balance did not increase due to that call (so if we didn't successfully settle to withdraw,
        //   the balance should not reflect an extra 1 ether from us).
        // - If settle succeeded (settleReverted == false) then it must have transferred 2 ether to this contract, so c.balance decreased by 2 ether.
        // We combine these into a single formula relating lockSucceeded, settleReverted, lockAmount, and the observed balance change.
        // Since we don't know initial balance, we reason about relative changes using only the facts that lockInGuess requires msg.value == 1 ether
        // and settle transfers 2 ether on a successful correct guess.

        // Build predicates:
        bool lockAmountIsOneEther = (lockAmount == 1 ether);
        bool implies_lock_effect = (!lockSucceeded) || lockAmountIsOneEther; // if lock succeeded it must have been with 1 ether

        // If settle succeeded then either there was a correct guess and contract paid out 2 ether, which requires its balance >= 2 ether before transfer.
        // We cannot inspect prior balances, so assert logical relations only:
        // - If settle succeeded then lock must have succeeded earlier (otherwise no guess to settle) OR there was a prior guess from before this run
        //   (but c was freshly deployed by the harness so prior guess cannot exist). The harness deploys a fresh c, so any successful settle in this run
        //   implies lockSucceeded == true. We assert that implication.
        bool settle_impl_lock = !settleReverted ? lockSucceeded : true;

        // Final assert: the two logical properties above must hold.
        assert(implies_lock_effect && settle_impl_lock);
    }

    // allow receiving Ether so settle's transfer can succeed
    receive() external payable {}
}
